# owner: platform
"""Snap span times to a fixed step for payroll."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span

def _check_step(step: int) -> None:
    if not isinstance(step, int) or step <= 0 or 60 % step:
        raise ValueError(
            f"step must divide an hour evenly: {step!r}"
        )

def _snap(minutes: int, step: int) -> int:
    """Nearest multiple of step. Halves round up."""
    return (minutes + step // 2) // step * step

def _label(span: Span) -> str:
    hours, rest = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {rest}m)"

# ---
def round_span(span: Span, step: int) -> Span:
    """Snap both ends of a span to the nearest step."""
    _check_step(step)
    return Span(
        _snap(span.start, step),
        _snap(span.end, step)
    )

# ---
def label_spans(spans: Iterable[Span], step: int) -> List[str]:
    """Labels such as 09:00-17:15 (8h 15m), after rounding."""
    _check_step(step)
    rounded = [round_span(span, step) for span in spans]
    return [_label(span) for span in rounded]

