# owner: platform
import unittest

from hourglass.rounding import label_spans, round_span
from hourglass.models import Span

class RoundSpanTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        span = Span(9 * 60 + 7, 17 * 60 + 7)
        self.assertEqual(
            round_span(span, 15), Span(9 * 60, 17 * 60)
        )

    def test_halves_round_up(self):
        self.assertEqual(
            round_span(Span(67, 128), 15), Span(60, 135)
        )

    def test_end_can_reach_midnight(self):
        self.assertEqual(
            round_span(Span(60, 1438), 15), Span(60, 1440)
        )

    def test_collapsed_span_is_rejected(self):
        with self.assertRaises(ValueError):
            round_span(Span(60, 64), 15)

class LabelTests(unittest.TestCase):
    def test_label_format(self):
        spans = [Span(9 * 60 + 2, 17 * 60 + 14)]
        self.assertEqual(
            label_spans(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_one_label_per_span(self):
        spans = [Span(0, 60), Span(61, 119)]
        self.assertEqual(
            label_spans(spans, 30),
            ["00:00-01:00 (1h 0m)", "01:00-02:00 (1h 0m)"]
        )

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 25, 90, 2.5):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    label_spans([Span(0, 60)], step)

    def test_bad_step_raises_for_empty_list(self):
        with self.assertRaises(ValueError):
            label_spans([], 0)
